-- GENERATED by tools/pok_hub_restock.py; canonical entry point for apply-era and operators.
-- Arrival-hub stock uses audited ORIGINAL class levels, never widened spells_new classes.
-- Preserves current item availability, merchant restrictions, and item prices.
-- Approved inventory: expansion 0, level cap 1..50. Review a new catalog before later releases.
-- Legacy archetype behavior is retained only while no arrival-hub NPCs/stock exist.
-- Run with mysql without --force. A failure rolls back the entire restock.
DELIMITER //
BEGIN NOT ATOMIC
DECLARE n BIGINT;
DECLARE hub_count INT;
DECLARE cap_text VARCHAR(100);
DECLARE half_count INT;
DECLARE held INT DEFAULT 0;
DECLARE EXIT HANDLER FOR SQLEXCEPTION
BEGIN
ROLLBACK;
DROP TEMPORARY TABLE IF EXISTS nightcap_pok_desired_stock;
IF held=1 THEN DO RELEASE_LOCK('nightcap_pok_hub'); END IF;
RESIGNAL;
END;
SELECT GET_LOCK('nightcap_pok_hub',0) INTO held;
IF held<>1 OR held IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='PoK content operation already running'; END IF;
SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
START TRANSACTION;
SELECT COUNT(*) INTO n FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='merchantlist' AND ENGINE='InnoDB';
IF n<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Merchant restock requires InnoDB'; END IF;
SELECT COUNT(*) INTO n FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND EVENT_OBJECT_TABLE='merchantlist';
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Review merchantlist triggers before restocking'; END IF;
SET cap_text=(SELECT rule_value FROM rule_values WHERE rule_name='Character:MaxLevel' AND ruleset_id=1);
IF cap_text IS NULL OR cap_text NOT REGEXP '^[0-9]+$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or invalid level cap'; END IF;
SET @cap=CAST(cap_text AS UNSIGNED);
IF @cap IS NULL OR @cap NOT BETWEEN 1 AND 255 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Missing or invalid level cap'; END IF;
SELECT COUNT(*) INTO hub_count FROM npc_types WHERE id BETWEEN 997900 AND 997915 OR merchant_id BETWEEN 99300 AND 99315 FOR UPDATE;
IF hub_count=0 THEN
SELECT COUNT(*) INTO n FROM merchantlist WHERE merchantid BETWEEN 99300 AND 99315 FOR UPDATE;
IF n<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Arrival stock exists without hub NPCs'; END IF;
-- Caster: Necromancer, Wizard, Magician, Enchanter
DELETE FROM merchantlist WHERE merchantid = 99221;
SELECT 99221, ROW_NUMBER() OVER (ORDER BY i.Name, i.id), i.id
FROM items i JOIN spells_new sn ON sn.id = i.scrolleffect
WHERE i.itemtype = 20 AND i.scrolleffect > 0
  -- one scroll per spell: PEQ ships several item copies of the same scroll
  -- (one per original class vendor); without this the vendor shows dupes (#9)
  AND i.id = (SELECT MIN(i2.id) FROM items i2
              WHERE i2.scrolleffect = i.scrolleffect AND i2.itemtype = 20)
  AND LEAST(
        IF(sn.classes11 BETWEEN 1 AND 254, sn.classes11, 255),
        IF(sn.classes12 BETWEEN 1 AND 254, sn.classes12, 255),
        IF(sn.classes13 BETWEEN 1 AND 254, sn.classes13, 255),
        IF(sn.classes14 BETWEEN 1 AND 254, sn.classes14, 255)) <= @cap;

-- Priest: Cleric, Druid, Shaman
DELETE FROM merchantlist WHERE merchantid = 99222;
SELECT 99222, ROW_NUMBER() OVER (ORDER BY i.Name, i.id), i.id
FROM items i JOIN spells_new sn ON sn.id = i.scrolleffect
WHERE i.itemtype = 20 AND i.scrolleffect > 0
  -- one scroll per spell: PEQ ships several item copies of the same scroll
  -- (one per original class vendor); without this the vendor shows dupes (#9)
  AND i.id = (SELECT MIN(i2.id) FROM items i2
              WHERE i2.scrolleffect = i.scrolleffect AND i2.itemtype = 20)
  AND LEAST(
        IF(sn.classes2  BETWEEN 1 AND 254, sn.classes2,  255),
        IF(sn.classes6  BETWEEN 1 AND 254, sn.classes6,  255),
        IF(sn.classes10 BETWEEN 1 AND 254, sn.classes10, 255)) <= @cap;

-- Melee: Ranger, Bard, Beastlord
DELETE FROM merchantlist WHERE merchantid = 99223;
SELECT 99223, ROW_NUMBER() OVER (ORDER BY i.Name, i.id), i.id
FROM items i JOIN spells_new sn ON sn.id = i.scrolleffect
WHERE i.itemtype = 20 AND i.scrolleffect > 0
  -- one scroll per spell: PEQ ships several item copies of the same scroll
  -- (one per original class vendor); without this the vendor shows dupes (#9)
  AND i.id = (SELECT MIN(i2.id) FROM items i2
              WHERE i2.scrolleffect = i.scrolleffect AND i2.itemtype = 20)
  AND LEAST(
        IF(sn.classes4  BETWEEN 1 AND 254, sn.classes4,  255),
        IF(sn.classes8  BETWEEN 1 AND 254, sn.classes8,  255),
        IF(sn.classes15 BETWEEN 1 AND 254, sn.classes15, 255)) <= @cap;

-- Tank: Paladin, Shadow Knight
DELETE FROM merchantlist WHERE merchantid = 99224;
SELECT 99224, ROW_NUMBER() OVER (ORDER BY i.Name, i.id), i.id
FROM items i JOIN spells_new sn ON sn.id = i.scrolleffect
WHERE i.itemtype = 20 AND i.scrolleffect > 0
  -- one scroll per spell: PEQ ships several item copies of the same scroll
  -- (one per original class vendor); without this the vendor shows dupes (#9)
  AND i.id = (SELECT MIN(i2.id) FROM items i2
              WHERE i2.scrolleffect = i.scrolleffect AND i2.itemtype = 20)
  AND LEAST(
        IF(sn.classes3 BETWEEN 1 AND 254, sn.classes3, 255),
        IF(sn.classes5 BETWEEN 1 AND 254, sn.classes5, 255)) <= @cap;

-- =============================================================================
-- Overflow split (#21): RoF2 shows at most 500 merchant items. Move each over-cap
-- vendor's second alphabetical half onto its "II" partner (spell_vendor_split.sql
-- creates those NPCs). Base keeps slots 1..half; II gets the rest, re-numbered.
-- Partners: Arcane 99221->99251, Divine 99222->99252, Tank 99224->99253.
-- Melee 99223 is small (never splits) and has no II vendor.
-- =============================================================================

SELECT COUNT(*) INTO n FROM merchantlist WHERE merchantid=99221;
DELETE FROM merchantlist WHERE merchantid=99251;
IF n > 480 THEN
SET half_count=CEIL(n/2);
 SELECT 99251,ROW_NUMBER() OVER (ORDER BY slot),item FROM merchantlist WHERE merchantid=99221 AND slot>half_count;
DELETE FROM merchantlist WHERE merchantid=99221 AND slot>half_count;
END IF;

SELECT COUNT(*) INTO n FROM merchantlist WHERE merchantid=99222;
DELETE FROM merchantlist WHERE merchantid=99252;
IF n > 480 THEN
SET half_count=CEIL(n/2);
 SELECT 99252,ROW_NUMBER() OVER (ORDER BY slot),item FROM merchantlist WHERE merchantid=99222 AND slot>half_count;
DELETE FROM merchantlist WHERE merchantid=99222 AND slot>half_count;
END IF;

SELECT COUNT(*) INTO n FROM merchantlist WHERE merchantid=99224;
DELETE FROM merchantlist WHERE merchantid=99253;
IF n > 480 THEN
SET half_count=CEIL(n/2);
 SELECT 99253,ROW_NUMBER() OVER (ORDER BY slot),item FROM merchantlist WHERE merchantid=99224 AND slot>half_count;
DELETE FROM merchantlist WHERE merchantid=99224 AND slot>half_count;
END IF;

ELSE
